-- DEC-032: hospitals.id is generated by PostgreSQL.
-- hospitals.id is also a column of the declared foreign key hospitals_address_same_tenant_fkey
-- (DEC-031), and Prisma does not apply @default(uuid()) to foreign-key columns. Setting a column
-- default changes no existing row and drops nothing. gen_random_uuid() is built into PostgreSQL 13+.

-- AlterTable
ALTER TABLE "hospitals" ALTER COLUMN "id" SET DEFAULT gen_random_uuid();
